/* ==========================================================================
   HÚNGARA LANCHES · IDENTIDADE VISUAL DO GEOMARKETING
   Logo, pin do mapa e a fonte Omnes SemiCond — em base64, num arquivo só.
   Muda quase nunca. Qualquer HTML da Húngara carrega este arquivo e ganha:
     window.HUNGARA_MARCA.logo / .pin / .fonte  (data-URLs)
     <img data-marca="logo">  ou  <img data-marca="pin">  → src preenchido
     a fonte 'Omnes' passa a existir no CSS da página
   ========================================================================== */
(function(){
  var M = {
    logo: "data:image/png;base64,",
    pin:  "data:image/png;base64,",
    fonte:"data:font/ttf;base64,"
  };
  M.fonteCSS = "@font-face{font-family:'Omnes';src:url(" + M.fonte + ") format('truetype');font-weight:600;font-display:swap}";
  M.aplicar = function(raiz){
    (raiz||document).querySelectorAll('img[data-marca]').forEach(function(el){
      var v = M[el.getAttribute('data-marca')];
      if(v && el.getAttribute('src')!==v) el.src = v;
    });
  };
  var st = document.createElement('style');
  st.textContent = M.fonteCSS;
  (document.head||document.documentElement).appendChild(st);
  window.HUNGARA_MARCA = M;
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', function(){ M.aplicar(); });
  else M.aplicar();
})();
